 root=D/'runs'/name;shutil.copytree(D/'fixtures'/case['id'],root/'workspace');job=ReadOnlyJob(task_id=name,request=request,workspace=str(root/'workspace'),output_dir=str(root/'execution'),max_calls=calls,max_seconds=240,tool_scope='files');save(root/'JOB.json',job.__dict__);r=run_read_only_job(job,settings=sett);print(name,r['termination'],r['generation_started'],flush=True);return r
if __name__=='__main__':
 reg=json.loads((D/'REGISTRATION.json').read_text());assert all(v.file_digest(R/p)==s for p,s in reg['source_pins'].items());assert v.file_digest(Path(__file__))==reg['runner_sha256'];sett=settings(reg);traces={}
 for c in reg['cases']:
  x=c['source_block'];q=c['request'];request=reg['common_prefix']+x+'\n<question>\n'+q+'\n</question>\n'+reg['t_instruction'];r=runjob(c['id']+'-notes-r1',request,c,sett)
  traces[c['id']]=r['final'] if r['termination']=='submitted' and r['final'] and r['final'].strip() else None
 save(D/'T_FROZEN.json',{cid:{'text':t,'sha256':v.digest(t),'eligible':t is not None,'selection':'only first run; no correction or quality selection'} for cid,t in traces.items()})
 for rep in (1,2):
  for arm in (reg['arms'] if rep==1 else list(reversed(reg['arms']))):
   for c in (reg['cases'] if rep==1 else list(reversed(reg['cases']))):
    name=f'{c["id"]}-{arm}-r{rep}';x=c['source_block'];q='<question>\n'+c['request']+'\n</question>';t=traces[c['id']]
    if arm in ('append','prefix') and t is None:save(D/'skipped'/f'{name}.json',{'reason':'T generation failed','method_failure':True});continue
    tblock='<unverified_model_notes>\n'+(t or '')+'\n</unverified_model_notes>'
    blocks={'original':[x,q],'reread':[x,q,x,q],'append':[x,tblock,q],'prefix':[tblock,x,q]}[arm];request=reg['common_prefix']+'\n'.join(blocks)
    runjob(name,request,c,sett)
 # Same complete jobs, serial versus two isolated worker processes. No other track uses RWKV concurrently.
 for mode,rep in [('serial',1),('parallel',1),('parallel',2),('serial',2)]:
  jobs=[]
