   name=f'{c["id"]}-{mode}-r{rep}';root=D/'runs'/name;shutil.copytree(D/'fixtures'/c['id'],root/'workspace');job=ReadOnlyJob(task_id=name,request=c['request'],workspace=str(root/'workspace'),output_dir=str(root/'execution'),max_calls=4,max_seconds=360,tool_scope='files');jobs.append(job);save(root/'JOB.json',job.__dict__)
